import math

def solve_for_n(n):
    # We solve 3r^2 - 3nr + (n^2 - 2007) = 0 for integer r

    # Discriminant D = 24104 - 3n^2
    D = 24104 - 3 * n**2

    if D < 0:
        return None

    k = int(math.isqrt(D))

    if k * k != D:
        # D is not a perfect square
        return None

    # Check the two possible roots for r
    roots = []

    # Check r1 = (3n + k) / 6
    num1 = 3 * n + k
    if num1 % 6 == 0:
        r1 = num1 // 6
        if 0 <= r1 <= n:
            roots.append(r1)

    # Check r2 = (3n - k) / 6
    num2 = 3 * n - k
    if num2 % 6 == 0:
        r2 = num2 // 6
        if 0 <= r2 <= n:
            roots.append(r2)

    return sorted(list(set(roots)))

n_values = range(1, 11)
results = {}

for n in n_values:
    solutions = solve_for_n(n)
    if solutions:
        results[n] = solutions

print(results)
